∀ {M : Type u_1} [inst : TopologicalSpace.{u_1} M] (c : ContinuousMap.{0, u_1} GC.Topology.TorusCylinder M) (r s : ℝ)
  (x : GC.Topology.Torus),
  Function.Injective.{1, u_1 + 1}
      ⇑(FundamentalGroup.map.{0, u_1} (ContinuousMap.comp.{0, 0, u_1} c (GC.Topology.torusAt r)) x) ↔
    Function.Injective.{1, u_1 + 1}
      ⇑(FundamentalGroup.map.{0, u_1} (ContinuousMap.comp.{0, 0, u_1} c (GC.Topology.torusAt s)) x)

