    GC.LongTime.hasLateSequenceTests.{u} F K →
      ∃ B,
        ∀ (s : GC.LongTime.RegularSlice.{u} (GC.Interface.RawSurgery.observation.{u} F)),
          LT.lt.{0} B (GC.LongTime.RegularSlice.time.{u} s) →
            Nonempty.{u + 1}
                (DifferentialGeometry.PDE.RicciFlow.Surgery.Topology.OrientedThreeStage.Carrier.{u}
                  (GC.LongTime.RegularSlice.stage.{u} s)) →
              GC.Endpoint.ComponentsGeometrize.{u}
                (DifferentialGeometry.PDE.RicciFlow.Surgery.Topology.OrientedThreeStage.toClosedOrientedManifold.{u}
                  (GC.LongTime.RegularSlice.stage.{u} s))

